// BEFORE STREAMS: nested for-loops, if-checks, manual accumulators — 80+ lines
package com.bank.settlement.service;

import com.bank.settlement.dto.SettlementReport;
import com.bank.settlement.model.Trade;
import com.bank.settlement.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class ImperativeReportService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public SettlementReport generateReport(LocalDate date) {
        List<Trade> allTrades = tradeRepo.findByTradeDate(date);

        // Step 1: Filter settled trades — manual loop + if
        List<Trade> settledTrades = new ArrayList<>();
        for (Trade trade : allTrades) {
            if (trade.isSettled()) {
                settledTrades.add(trade);
            }
        }

        // Step 2: Calculate buy total — manual accumulator
        BigDecimal totalBuy = BigDecimal.ZERO;
        for (Trade trade : settledTrades) {
            if (trade.isBuy()) {
                totalBuy = totalBuy.add(trade.getAmount());
            }
        }

        // Step 3: Calculate sell total — another manual accumulator
        BigDecimal totalSell = BigDecimal.ZERO;
        for (Trade trade : settledTrades) {
            if (!trade.isBuy()) {
                totalSell = totalSell.add(trade.getAmount());
            }
        }

        // Step 4: Unique symbols sorted — manual Set + sort
        Set<String> symbolSet = new TreeSet<>();
        for (Trade trade : settledTrades) {
            symbolSet.add(trade.getSymbol());
        }
        List<String> topSymbols = new ArrayList<>(symbolSet);

        // Step 5: Unique accounts — manual Set
        Set<String> accountSet = new HashSet<>();
        for (Trade trade : settledTrades) {
            accountSet.add(trade.getAccountId());
        }

        BigDecimal net = totalBuy.subtract(totalSell);
        log.info("[IMPERATIVE] {} settled trades, net: Rs.{} — required 5 separate loops!",
            settledTrades.size(), net);

        return new SettlementReport("IMPERATIVE", date.toString(),
            settledTrades.size(), totalBuy, totalSell, net,
            topSymbols, String.join(", ", accountSet));
    }
}
