// AFTER STREAMS: declarative pipeline — 15 lines for the same logic
package com.bank.settlement.service;

import com.bank.settlement.dto.SettlementReport;
import com.bank.settlement.model.Trade;
import com.bank.settlement.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class StreamReportService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public SettlementReport generateReport(LocalDate date) {
        // SOURCE: Collection → Stream<Trade>
        List<Trade> settled = tradeRepo.findByTradeDate(date).stream()
            .filter(Trade::isSettled)       // INTERMEDIATE: filter settled
            .toList();                      // TERMINAL: collect

        // Buy total — one pipeline
        BigDecimal totalBuy = settled.stream()
            .filter(Trade::isBuy)           // INTERMEDIATE: filter buys
            .map(Trade::getAmount)          // INTERMEDIATE: extract amount
            .reduce(BigDecimal.ZERO, BigDecimal::add);  // TERMINAL: sum

        // Sell total — one pipeline
        BigDecimal totalSell = settled.stream()
            .filter(t -> !t.isBuy())        // INTERMEDIATE: filter sells
            .map(Trade::getAmount)          // INTERMEDIATE: extract amount
            .reduce(BigDecimal.ZERO, BigDecimal::add);  // TERMINAL: sum

        // Unique symbols sorted — one pipeline
        List<String> topSymbols = settled.stream()
            .map(Trade::getSymbol)          // INTERMEDIATE: extract symbol
            .distinct()                     // INTERMEDIATE: unique (stateful)
            .sorted()                       // INTERMEDIATE: sort (stateful)
            .toList();                      // TERMINAL: collect

        // Unique accounts — one pipeline
        String accounts = settled.stream()
            .map(Trade::getAccountId)       // INTERMEDIATE: extract accountId
            .distinct()                     // INTERMEDIATE: unique
            .collect(Collectors.joining(", ")); // TERMINAL: join to string

        BigDecimal net = totalBuy.subtract(totalSell);
        log.info("[STREAM] {} settled trades, net: Rs.{} — clean declarative pipelines!",
            settled.size(), net);

        return new SettlementReport("STREAM", date.toString(),
            settled.size(), totalBuy, totalSell, net,
            topSymbols, accounts);
    }

    // ═══ DEMONSTRATE: stream is single-use ═══
    public void demonstrateSingleUse() {
        var stream = List.of("RELIANCE", "TCS", "HDFC").stream()
            .filter(s -> s.length() > 3);

        long count = stream.count();  // TERMINAL — stream consumed
        log.info("Count: {}", count);

        // stream.forEach(System.out::println);
        // ↑ THROWS IllegalStateException: "stream has already been operated upon or closed"
        // Solution: create a new stream from the source collection
    }
}
