package com.bank.settlement.controller;

import com.bank.settlement.dto.SettlementReport;
import com.bank.settlement.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.*;
import java.time.LocalDate;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/settlement")
@RequiredArgsConstructor
public class SettlementController {

    private final ImperativeReportService imperativeService;
    private final StreamReportService streamService;

    @GetMapping("/imperative")
    public SettlementReport imperativeReport(
        @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date
    ) {
        return imperativeService.generateReport(date);
    }

    @GetMapping("/stream")
    public SettlementReport streamReport(
        @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date
    ) {
        return streamService.generateReport(date);
    }

    @GetMapping("/compare")
    public Map<String, SettlementReport> compare(
        @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate date
    ) {
        return Map.of(
            "imperative", imperativeService.generateReport(date),
            "stream", streamService.generateReport(date)
        );
    }
}
