package com.bank.settlement.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class StreamVsImperativeTest {

    @Test
    void streamHasThreeComponents() {
        List<String> symbols = List.of("RELIANCE", "TCS", "HDFC", "TCS", "WIPRO");

        long count = symbols.stream()     // SOURCE: List → Stream
            .filter(s -> s.length() > 3)   // INTERMEDIATE: filter (lazy)
            .distinct()                    // INTERMEDIATE: unique (lazy)
            .count();                      // TERMINAL: triggers execution

        assertThat(count).isEqualTo(3);    // RELIANCE, HDFC, WIPRO
    }

    @Test
    void streamDoesNotStoreElements() {
        // Stream is a PIPELINE, not a data structure
        Stream<String> stream = Stream.of("RELIANCE", "TCS");
        // stream has NO size() method — it does not know how many elements it has!
        // stream has NO get(index) method — no random access!
        // It only knows how to pull elements one at a time through the pipeline.
        long count = stream.count();
        assertThat(count).isEqualTo(2);
    }

    @Test
    void streamIsSingleUse() {
        Stream<String> stream = Stream.of("RELIANCE", "TCS", "HDFC");
        stream.count();  // consumed

        assertThatThrownBy(() -> stream.forEach(System.out::println))
            .isInstanceOf(IllegalStateException.class)
            .hasMessageContaining("stream has already been operated upon or closed");
    }

    @Test
    void intermediateOpsAreLazy() {
        List<String> log = new java.util.ArrayList<>();

        Stream<String> pipeline = List.of("RELIANCE", "TCS").stream()
            .filter(s -> { log.add("filter:" + s); return true; })
            .map(s -> { log.add("map:" + s); return s.toLowerCase(); });

        // NO terminal operation yet — filter and map have NOT executed!
        assertThat(log).isEmpty();

        // Now trigger with terminal:
        pipeline.toList();
        assertThat(log).isNotEmpty();  // NOW they executed!
    }

    @Test
    void reduceAccumulatesValue() {
        BigDecimal total = Stream.of("245050", "176000", "33664")
            .map(BigDecimal::new)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        assertThat(total).isEqualByComparingTo("454714");
    }

    @Test
    void collectionIsReusable() {
        List<String> symbols = List.of("RELIANCE", "TCS");

        // Collection can be iterated multiple times:
        long count1 = symbols.stream().count();
        long count2 = symbols.stream().count();  // NEW stream, same source
        assertThat(count1).isEqualTo(count2);
    }
}
